import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, positionLocal, color, mix, vec3, float, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Shape, ExtrudeGeometry, DirectionalLight } = ctx.THREE;

  const colors = (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || {};
  const C = {
    background: colors.background || '#0b0b10',
    surface: colors.surface || '#14141a',
    paper: colors.paper || '#e8ecf2',
    accent: colors.accent || '#ff2a38',
    grad0: (colors.gradientStops && colors.gradientStops[0] && colors.gradientStops[0].hex) || '#101017',
    grad1: (colors.gradientStops && colors.gradientStops[1] && colors.gradientStops[1].hex) || '#1a1a22'
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const txt = (role, fallback) => {
    const found = items.filter((i) => i.role === role);
    return found.length ? found : [{ text: fallback }];
  };
  // Ordered pull with graceful fallback to spec copy
  const getText = (idx, fallback) => (items[idx] && items[idx].text) ? items[idx].text : fallback;
  const captionStr = getText(0, 'ATELIER METRICS / Q2 2026');
  const heroValue = getText(1, '0.002 mm');
  const heroLabel = getText(2, 'Case tolerance, CNC pass');
  const val2 = getText(3, '38 h');
  const lab2 = getText(4, 'Power reserve, NA-01');
  const val3 = getText(5, '214');
  const lab3 = getText(6, 'Components per calibre');

  const root = new Group();
  root.name = 'bento-metrics-grid';

  const disposables = [];
  const timelines = [];
  const primHandles = [];

  // ---------- BACKDROP STAGE (7 x 6 vertical gradient, z = -2.5) ----------
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color(C.grad0), color(C.grad1), uv().y);
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, -0.25, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- LOCAL RIM LIGHT (accent hue, back-right) ----------
  const rim = new DirectionalLight(C.accent, 0.8);
  rim.position.set(3.5, -1.5, -1.5);
  rim.target.position.set(0, 0, 0);
  root.add(rim);
  root.add(rim.target);

  // ---------- CELL FACTORY ----------
  const cellGroups = [];

  function makeSlab(w, h) {
    const bevel = 0.04;
    const shape = new Shape();
    const hw = w / 2 - bevel;
    const hh = h / 2 - bevel;
    shape.moveTo(-hw, -hh);
    shape.lineTo(hw, -hh);
    shape.lineTo(hw, hh);
    shape.lineTo(-hw, hh);
    shape.closePath();
    const geo = new ExtrudeGeometry(shape, {
      depth: 0.06,
      bevelEnabled: true,
      bevelThickness: bevel,
      bevelSize: bevel,
      bevelSegments: 2
    });
    geo.center();

    // Face material: engineered 135-deg diagonal gradient + hard machined sheen band
    const faceMat = new MeshStandardNodeMaterial();
    const diag = Math.sqrt(w * w + h * h);
    const t = positionLocal.x.div(w).sub(positionLocal.y.div(h)).mul(0.5).add(0.5);
    const base = mix(color(C.grad0), color(C.grad1), t);
    const bw = 0.15 / diag;
    const b0 = 0.4 - bw / 2;
    const b1 = 0.4 + bw / 2;
    const band = smoothstep(float(b0 - 0.004), float(b0), t).mul(
      float(1.0).sub(smoothstep(float(b1), float(b1 + 0.004), t))
    );
    faceMat.colorNode = base.add(vec3(0.06, 0.06, 0.06).mul(band));
    faceMat.roughness = 0.55;
    faceMat.metalness = 0.35;
    faceMat.transparent = true;
    faceMat.opacity = 1;

    // Edge material: brushed metal chamfer that catches the key light
    const edgeMat = new MeshPhysicalNodeMaterial();
    edgeMat.color.set(C.surface);
    edgeMat.roughness = 0.5;
    edgeMat.metalness = 0.45;
    edgeMat.clearcoat = 0.2;
    edgeMat.transparent = true;
    edgeMat.opacity = 1;

    const mesh = new Mesh(geo, [faceMat, edgeMat]);
    disposables.push(geo, faceMat, edgeMat);
    return { mesh, mats: [faceMat, edgeMat] };
  }

  function makeTick() {
    const geo = new BoxGeometry(0.4, 0.05, 0.02);
    const mat = new MeshStandardNodeMaterial();
    mat.color.set(C.accent);
    mat.emissive.set(C.accent);
    mat.emissiveIntensity = 1.3;
    mat.roughness = 0.5;
    mat.transparent = true;
    mat.opacity = 1;
    const mesh = new Mesh(geo, mat);
    disposables.push(geo, mat);
    return { mesh, mat };
  }

  function makeCell(w, h, cx, cy, content) {
    const g = new Group();
    g.position.set(cx, cy, 0);
    const cellMats = [];

    const slab = makeSlab(w, h);
    g.add(slab.mesh);
    cellMats.push(...slab.mats);

    const zFront = 0.09;
    const padX = -w / 2 + 0.5;

    const tick = makeTick();
    tick.mesh.position.set(padX + 0.2, h / 2 - 0.5 - 0.025, zFront);
    g.add(tick.mesh);
    cellMats.push(tick.mat);

    for (const c of content) {
      const t = ctx.fontAtlas.createText(c.text, {
        fontSize: c.fontSize,
        color: c.color || C.paper,
        align: 'left',
        letterSpacingPx: c.letterSpacingPx || 0
      });
      t.position.set(padX, c.y, zFront);
      g.add(t);
      t.traverse((o) => {
        if (o.material) {
          o.material.transparent = true;
          cellMats.push(o.material);
        }
      });
    }

    g.userData.fadeMats = cellMats;
    root.add(g);
    cellGroups.push(g);
    return g;
  }

  // ---------- GRID GEOMETRY: 5.5 x 3.5, gutter 0.25 ----------
  // Dominant: 3.25 x 3.5 left column (center x -1.125). Secondary: 2.0 x 1.625 right column.
  makeCell(3.25, 3.5, -1.125, 0, [
    { text: heroValue, fontSize: 124, y: 0.1, letterSpacingPx: -1.2 },
    { text: heroLabel, fontSize: 18, y: -0.5, letterSpacingPx: 1.4 }
  ]);
  makeCell(2.0, 1.625, 1.75, 0.9375, [
    { text: val2, fontSize: 68, y: -0.05, letterSpacingPx: -0.3 },
    { text: lab2, fontSize: 18, y: -0.45, letterSpacingPx: 1.4 }
  ]);
  makeCell(2.0, 1.625, 1.75, -0.9375, [
    { text: val3, fontSize: 68, y: -0.05, letterSpacingPx: -0.3 },
    { text: lab3, fontSize: 18, y: -0.45, letterSpacingPx: 1.4 }
  ]);

  // ---------- HEADER CAPTION (0.5 above grid, left-aligned to x = -2.75) ----------
  const caption = ctx.fontAtlas.createText(captionStr, {
    fontSize: 18,
    color: C.paper,
    align: 'left',
    letterSpacingPx: 2.2
  });
  caption.position.set(-2.75, 2.25, 0.05);
  root.add(caption);

  // ---------- FOREGROUND ACCENT PLANE (third depth layer) ----------
  const fgGeo = new PlaneGeometry(1.1, 0.015);
  const fgMat = new MeshBasicNodeMaterial();
  fgMat.colorNode = vec3(1.0, 0.165, 0.22);
  fgMat.transparent = true;
  fgMat.opacity = 0.85;
  const fgLine = new Mesh(fgGeo, fgMat);
  fgLine.position.set(-2.2, -2.15, 0.6);
  root.add(fgLine);
  disposables.push(fgGeo, fgMat);

  // ---------- ENTRANCE: stagger-cards fade-up, dominant first ----------
  const entrance = gsap.timeline();
  timelines.push(entrance);
  cellGroups.forEach((g, i) => {
    const baseY = g.position.y;
    g.position.y = baseY + 0.2;
    const mats = g.userData.fadeMats;
    mats.forEach((m) => { m.opacity = 0; });
    entrance.to(g.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power2.out'
    }, i * 0.08);
    entrance.to(mats, {
      opacity: 1,
      duration: 0.5,
      ease: 'power2.out'
    }, i * 0.08);
  });
  entrance.fromTo(caption.position,
    { y: 2.45 },
    { y: 2.25, duration: 0.6, ease: 'power3.out' },
    0.05
  );

  // ---------- IDLE: single slow breathing (<= 2%) ----------
  const idle = gsap.to(root.scale, {
    x: 1.012, y: 1.012, z: 1.012,
    duration: 4.5,
    yoyo: true,
    repeat: -1,
    ease: 'sine.inOut'
  });
  timelines.push(idle);

  // ---------- APPLY CINEMATIC PRIMITIVES FROM CONFIG ----------
  const prims = config.cinematicPrimitives || [];
  for (const p of prims) {
    if (ctx.primitives && ctx.primitives[p.name]) {
      primHandles.push(ctx.primitives[p.name](root, p.params || {}));
    }
  }

  // ---------- INTERACTION: press-down / weighted-settle ----------
  root.userData.handlers = {
    pointerdown: () => {
      gsap.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' });
    },
    pointerup: () => {
      const tl = gsap.timeline();
      tl.to(root.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.18, ease: 'power2.out' })
        .to(root.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
      timelines.push(tl);
    },
    hover: () => {
      gsap.to(root.rotation, { y: 0.05, x: -0.02, duration: 0.3, ease: 'power2.out' });
    },
    unhover: () => {
      gsap.to(root.rotation, { y: 0, x: 0, duration: 0.3, ease: 'power2.out' });
    }
  };

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill && t.kill());
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(root.rotation);
    cellGroups.forEach((g) => gsap.killTweensOf(g.position));
    gsap.killTweensOf(caption.position);
    primHandles.forEach((h) => h && h.cleanup && h.cleanup());
    disposables.forEach((d) => d.dispose && d.dispose());
    root.traverse((o) => {
      if (o.geometry && !disposables.includes(o.geometry)) o.geometry.dispose && o.geometry.dispose();
    });
    rim.dispose && rim.dispose();
  };

  return root;
}
